#!/usr/bin/env python3
"""Capture the poster HTML as a high-quality PNG using Playwright."""

from playwright.sync_api import sync_playwright
import os

HTML_PATH = os.path.abspath("/app/output/poster.html")
OUTPUT_PATH = os.path.abspath("/app/output/final_poster.png")

# A1 portrait: 594mm x 841mm
# At ~105 DPI effective: 2480 x 3508
VIEWPORT_WIDTH = 1240
VIEWPORT_HEIGHT = 1754
DEVICE_SCALE = 2  # Final: 2480 x 3508 pixels

def capture():
    with sync_playwright() as p:
        browser = p.chromium.launch()
        page = browser.new_page(
            viewport={"width": VIEWPORT_WIDTH, "height": VIEWPORT_HEIGHT},
            device_scale_factor=DEVICE_SCALE,
        )
        page.goto(f"file://{HTML_PATH}", wait_until="networkidle")

        # Wait for fonts to load
        page.wait_for_function("document.fonts.ready", timeout=10000)

        # Wait for infographic charts to render (render signal)
        try:
            page.wait_for_function(
                "document.getElementById('render-signal').classList.contains('ready')",
                timeout=15000,
            )
        except Exception:
            print("Render signal not detected, proceeding after timeout...")

        # Extra wait for chart rendering to complete
        page.wait_for_timeout(3000)

        # Verify charts have SVG content
        charts_ok = page.evaluate("""() => {
            const ids = ['penetration-chart', 'population-chart', 'social-chart'];
            return ids.map(id => {
                const el = document.getElementById(id);
                return { id, hasSVG: el ? el.querySelector('svg') !== null : false };
            });
        }""")
        print("Chart render status:", charts_ok)

        # Take full-page screenshot
        page.screenshot(path=OUTPUT_PATH, full_page=False)
        print(f"Poster saved to {OUTPUT_PATH}")

        # Verify output
        size = os.path.getsize(OUTPUT_PATH)
        print(f"File size: {size:,} bytes")

        browser.close()

if __name__ == "__main__":
